mapper.select:
select t.fee_type_cd feeTypeCd,t.ft_id ftId,t.status_cd statusCd,t.ft_name ftName,
t.community_id communityId,month_amount monthAmount,td.`name` feeTypeCdName
from fee_type t
left join t_dict td on t.fee_type_cd = td.status_cd and td.table_name = 'pay_fee_config' and td.table_columns = 'fee_type_cd'
where 1 =1

    and t.fee_type_cd= #{feeTypeCd}


    and t.fee_type_cd in

        #{item}




    and t.ft_id= #{ftId}


    and t.status_cd= #{statusCd}


    and t.ft_name= #{ftName}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update fee_type t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.fee_type_cd= #{feeTypeCd}


    , t.ft_name= #{ftName}


    , t.month_amount= #{monthAmount}

where 1=1

    and t.ft_id= #{ftId}


    and t.community_id= #{communityId}

